window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2ff82c3a3023905d"]={"versions": [{"id": "FIG-2ff82c3a3023905d", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Metamodell-Infrastruktur eines AUTOSAR-Template-Modells im Rahmen des AUTOSAR Template Modeling Guide. Es definiert das strukturelle Fundament für die Modellierung von AUTOSAR-Beschreibungsdateien (ARXML) mit Wurzelknoten, Paketorganisation und allgemeinen Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert vier zentrale Klassen und ihre Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>Identifiable</strong> (Stereotyp <code>«atpIdentifiable»</code>, abstrakt): Basisklasse für identifizierbare Elemente mit den Attributen <code>shortName: Identifier</code>, <code>longName: String [0..1]</code>, <code>category: String [0..1]</code>, <code>uuid: String [0..1]</code>, <code>checksum: String [0..1]</code> und <code>timestamp: DateTime [0..1]</code>.\n</li><li><strong>AUTOSAR</strong>: Wurzelklasse des Metamodells. Sie aggregiert über eine Kompositionsbeziehung <code>+topLevelPackage</code> 0..* Exemplare von <code>ARPackage</code> (Multiplizität auf Wurzelseite: 0..1).\n</li><li><strong>ARPackage</strong> (Stereotyp <code>«atpIdentifiable»</code>): Erbt von <code>Identifiable</code>. Sie dient der hierarchischen Strukturierung und besitzt eine rekursive Komposition auf sich selbst mit Rollenbezeichnung <code>+subPackage</code> und Multiplizität 0..* (Elternseite: 0..1). Des Weiteren enthält sie eine Komposition <code>+element</code> mit Multiplizität 0..* zu <code>ARElement</code>.\n</li><li><strong>ARElement</strong> (Stereotyp <code>«atpIdentifiable»</code>, abstrakt): Erbt direkt von <code>Identifiable</code> und fungiert als Basis für konkrete Template- bzw. Modellelemente innerhalb eines Pakets.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Es definiert die statische Dekomposition und Schachtelungshierarchie eines XML-Dokuments von der AUTOSAR-Wurzel über Top-Level- und Sub-Packages bis hin zu den eigentlichen Modellelementen (<code>ARElement</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Basis für die Serialisierung und Instanziierung im AUTOSAR-Metamodell:</p>\n<ul class=\"fig-list\"><li>Jedes <code>ARPackage</code> und <code>ARElement</code> besitzt verpflichtend einen <code>shortName</code> zur Identifikation und Pfadbildung sowie optionale Metadaten (UUID, Prüfsumme, Zeitstempel).\n</li><li>Top-Level-Pakete müssen innerhalb des AUTOSAR-Wurzelelements abgelegt werden. Pakete können beliebig tief geschachtelt werden (<code>subPackage</code>).\n</li><li>Elemente (<code>ARElement</code>) dürfen nur innerhalb von <code>ARPackage</code> instanziiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9e8bee8acfec945b", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Metamodell-Infrastruktur eines AUTOSAR-Template-Modells im Rahmen des AUTOSAR Template Modeling Guide. Es definiert das strukturelle Fundament für die Modellierung von AUTOSAR-Beschreibungsdateien (ARXML) mit Wurzelknoten, Paketorganisation und allgemeinen Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Klassen, Namespaces und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>Identifiable::Identifiable</strong> (abstrakt): Basisklasse im Paket <code>Identifiable</code> mit den Attributen <code>category: String [0..1]</code>, <code>shortName: Identifier</code> und <code>uuid: String</code>.\n</li><li><strong>Identifiable::PackageableElement</strong> (abstrakt): Erbt generalisierend von <code>Identifiable::Identifiable</code>. Dient als abstrakte Basis für alle in Paketen einbettbaren Elemente.\n</li><li><strong>Autosar::ARPackage</strong>: Erbt von <code>Identifiable::PackageableElement</code>. Sie organisiert Modellelemente hierarchisch über eine reflexive Komposition <code>+subPackage</code> mit Multiplizität 0..* (Elternseite 0..1, Stereotyp <code>«splitable»</code>) und aggregiert über die Komposition <code>+element</code> 0..* Elemente vom Typ <code>Identifiable::PackageableElement</code> (Stereotyp <code>«splitable»</code>).\n</li><li><strong>Autosar::AUTOSAR</strong>: Wurzelklasse im Paket <code>Autosar</code>. Aggregiert per Komposition <code>+topLevelPackage</code> 0..* Instanzen von <code>Autosar::ARPackage</code> (Wurzelseite 0..1, Stereotyp <code>«splitable»</code>).\n</li><li><strong>Identifiable::ARElement</strong> (abstrakt): Erbt von <code>Identifiable::PackageableElement</code> und repräsentiert konkrete Template-Entitäten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Es definiert die statische Dekomposition und Schachtelungshierarchie eines XML-Dokuments von der AUTOSAR-Wurzel über Top-Level- und Sub-Packages bis hin zu den eigentlichen Modellelementen (<code>ARElement</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben für die Strukturierung und den Datenaustausch nach dem AUTOSAR-Metamodell:</p>\n<ul class=\"fig-list\"><li>Die Stereotypisierung von <code>topLevelPackage</code>, <code>subPackage</code> und <code>element</code> als <code>«splitable»</code> gestattet das Aufteilen von Paket- und Elementdefinitionen über mehrere physische Dateien hinweg (ARXML-Splitting).\n</li><li>Das Attribut <code>uuid</code> ist verpflichtend (<code>String [1]</code>), während <code>shortName</code> weiterhin als primärer Identifier dient. Die Attribute <code>longName</code>, <code>checksum</code> und <code>timestamp</code> sind auf dieser Ebene nicht mehr Teil von <code>Identifiable</code>.\n</li><li>Durch die Zwischenklasse <code>PackageableElement</code> können sowohl <code>ARElement</code> als auch verschachtelte Pakete (<code>ARPackage</code>) einheitlich über die Kompositionsrolle <code>+element</code> bzw. <code>+subPackage</code> verwaltet werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-07b95f966ac57c83", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Metamodell-Infrastruktur eines AUTOSAR-Template-Modells im Rahmen des AUTOSAR Template Modeling Guide. Es definiert das strukturelle Fundament für die Modellierung von AUTOSAR-Beschreibungsdateien (ARXML) mit Wurzelknoten, Paketorganisation und allgemeinen Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Klassen, Namespaces und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>Identifiable::Identifiable</strong> (abstrakt): Basisklasse im Paket <code>Identifiable</code> mit den Attributen <code>category: String [0..1]</code>, <code>shortName: Identifier</code> und <code>uuid: String</code>.\n</li><li><strong>Identifiable::PackageableElement</strong> (abstrakt): Erbt generalisierend von <code>Identifiable::Identifiable</code>. Dient als abstrakte Basis für alle in Paketen einbettbaren Elemente.\n</li><li><strong>Autosar::ARPackage</strong>: Erbt von <code>Identifiable::PackageableElement</code>. Sie organisiert Modellelemente hierarchisch über eine reflexive Komposition <code>+subPackage</code> mit Multiplizität 0..* (Elternseite 0..1, Stereotyp <code>«splitable»</code>) und aggregiert über die Komposition <code>+element</code> 0..* Elemente vom Typ <code>Identifiable::PackageableElement</code> (Stereotyp <code>«splitable»</code>).\n</li><li><strong>Autosar::AUTOSAR</strong>: Wurzelklasse im Paket <code>Autosar</code>. Aggregiert per Komposition <code>+topLevelPackage</code> 0..* Instanzen von <code>Autosar::ARPackage</code> (Wurzelseite 0..1, Stereotyp <code>«splitable»</code>).\n</li><li><strong>Identifiable::ARElement</strong> (abstrakt): Erbt von <code>Identifiable::PackageableElement</code> und repräsentiert konkrete Template-Entitäten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Es definiert die statische Dekomposition und Schachtelungshierarchie eines XML-Dokuments von der AUTOSAR-Wurzel über Top-Level- und Sub-Packages bis hin zu den eigentlichen Modellelementen (<code>ARElement</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben für die Strukturierung und den Datenaustausch nach dem AUTOSAR-Metamodell:</p>\n<ul class=\"fig-list\"><li>Die Stereotypisierung von <code>topLevelPackage</code>, <code>subPackage</code> und <code>element</code> als <code>«splitable»</code> gestattet das Aufteilen von Paket- und Elementdefinitionen über mehrere physische Dateien hinweg (ARXML-Splitting).\n</li><li>Das Attribut <code>uuid</code> ist verpflichtend (<code>String [1]</code>), während <code>shortName</code> weiterhin als primärer Identifier dient. Die Attribute <code>longName</code>, <code>checksum</code> und <code>timestamp</code> sind auf dieser Ebene nicht mehr Teil von <code>Identifiable</code>.\n</li><li>Durch die Zwischenklasse <code>PackageableElement</code> können sowohl <code>ARElement</code> als auch verschachtelte Pakete (<code>ARPackage</code>) einheitlich über die Kompositionsrolle <code>+element</code> bzw. <code>+subPackage</code> verwaltet werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6bc8a3f522ef2f1f", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Metamodell-Infrastruktur eines AUTOSAR-Template-Modells im Rahmen des AUTOSAR Template Modeling Guide. Es definiert das strukturelle Fundament für die Modellierung von AUTOSAR-Beschreibungsdateien (ARXML) mit Wurzelknoten, Paketorganisation und allgemeinen Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Klassen, Namespaces und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>Identifiable::Identifiable</strong> (abstrakt): Basisklasse im Paket <code>Identifiable</code> mit den Attributen <code>category: String [0..1]</code>, <code>shortName: Identifier</code> und <code>uuid: String</code>.\n</li><li><strong>Identifiable::PackageableElement</strong> (abstrakt): Erbt generalisierend von <code>Identifiable::Identifiable</code>. Dient als abstrakte Basis für alle in Paketen einbettbaren Elemente.\n</li><li><strong>Autosar::ARPackage</strong>: Erbt von <code>Identifiable::PackageableElement</code>. Sie organisiert Modellelemente hierarchisch über eine reflexive Komposition <code>+subPackage</code> mit Multiplizität 0..* (Elternseite 0..1, Stereotyp <code>«splitable»</code>) und aggregiert über die Komposition <code>+element</code> 0..* Elemente vom Typ <code>Identifiable::PackageableElement</code> (Stereotyp <code>«splitable»</code>).\n</li><li><strong>Autosar::AUTOSAR</strong>: Wurzelklasse im Paket <code>Autosar</code>. Aggregiert per Komposition <code>+topLevelPackage</code> 0..* Instanzen von <code>Autosar::ARPackage</code> (Wurzelseite 0..1, Stereotyp <code>«splitable»</code>).\n</li><li><strong>Identifiable::ARElement</strong> (abstrakt): Erbt von <code>Identifiable::PackageableElement</code> und repräsentiert konkrete Template-Entitäten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Es definiert die statische Dekomposition und Schachtelungshierarchie eines XML-Dokuments von der AUTOSAR-Wurzel über Top-Level- und Sub-Packages bis hin zu den eigentlichen Modellelementen (<code>ARElement</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben für die Strukturierung und den Datenaustausch nach dem AUTOSAR-Metamodell:</p>\n<ul class=\"fig-list\"><li>Die Stereotypisierung von <code>topLevelPackage</code>, <code>subPackage</code> und <code>element</code> als <code>«splitable»</code> gestattet das Aufteilen von Paket- und Elementdefinitionen über mehrere physische Dateien hinweg (ARXML-Splitting).\n</li><li>Das Attribut <code>uuid</code> ist verpflichtend (<code>String [1]</code>), während <code>shortName</code> weiterhin als primärer Identifier dient. Die Attribute <code>longName</code>, <code>checksum</code> und <code>timestamp</code> sind auf dieser Ebene nicht mehr Teil von <code>Identifiable</code>.\n</li><li>Durch die Zwischenklasse <code>PackageableElement</code> können sowohl <code>ARElement</code> als auch verschachtelte Pakete (<code>ARPackage</code>) einheitlich über die Kompositionsrolle <code>+element</code> bzw. <code>+subPackage</code> verwaltet werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2ff82c3a3023905d", "to": "FIG-9e8bee8acfec945b", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Pakethierarchie / Namespaces: Klassen führen nun Package-Präfixe (<code>Autosar::AUTOSAR</code>, <code>Autosar::ARPackage</code>, <code>Identifiable::Identifiable</code>, <code>Identifiable::ARElement</code>).\n</li><li>Stereotypen: Stereotyp «atpIdentifiable» an den Klassen entfernt; Assoziationen <code>topLevelPackage</code>, <code>subPackage</code> und <code>element</code> neu mit dem Stereotyp «splitable» versehen.\n</li><li>Vererbungshierarchie: Zwischenklasse <code>Identifiable::PackageableElement</code> eingeführt, von der <code>Autosar::ARPackage</code> und <code>Identifiable::ARElement</code> erben (ARElement erbt nicht mehr direkt von Identifiable); ARPackage aggregiert nun <code>+element: Identifiable::PackageableElement</code> statt direkt <code>ARElement</code>.\n</li><li>Attribute in <code>Identifiable::Identifiable</code>:\n<ul class=\"fig-list\"><li>Entfernt: <code>longName: String [0..1]</code>, <code>checksum: String [0..1]</code>, <code>timestamp: DateTime [0..1]</code>.\n</li><li>Geändert: Kardinalität von <code>uuid</code> von optional (<code>String [0..1]</code>) zu obligatorisch (<code>String [1]</code>).\n</li></ul>\n</li></ul>"}, {"from": "FIG-9e8bee8acfec945b", "to": "FIG-07b95f966ac57c83", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-07b95f966ac57c83", "to": "FIG-6bc8a3f522ef2f1f", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
